        VacationComponent.prototype.openStudentHelp = function () {
            var _this = this;
            var codesArray = this.filterRecord.student_code_list.join(',');
            var dialogRef = this.dialog.open(MilitaryStudentHelpComponent, {
                data: {
                    multiSelect: true,
                    previousSelectedArr: codesArray
                }
            });
            dialogRef.afterClosed().subscribe(function (dialogResult) {
                if ((typeof dialogResult !== 'undefined') && (dialogResult !== null)) {
                    if (_this.filterRecord.student_code_list.length > 0) {
                        var dialogRefConfirm = _this.dialog.open(DeleteConfirmComponent, {
                            data: {
                                message: _this.i18n.get('academicMilitary.vacation.data_found', 'Delete this Record ?'),
                                yes: _this.i18n.get('academicMilitary.vacation.merge', 'Merge'),
                                no: _this.i18n.get('academicMilitary.vacation.replace', "Replace")
                            }
                        });
                        dialogRefConfirm.afterClosed().subscribe(function (res) {
                            if (res == true) {
                                _this.merge(dialogResult);
                            }
                            else {
                                _this.replace(dialogResult);
                            }
                        });
                    }
                    else {
                        _this.replace(dialogResult);
                    }
                }
            });
        };
        VacationComponent.prototype.merge = function (dialogResult) {
            var _this = this;
            var studentArray = dialogResult;
            studentArray.forEach(function (element) {
                if (!_this.filterRecord.student_code_list.includes(element.student_code)) {
                    _this.filterRecord.student_code_list.push(element.student_code);
                    var obj = {
                        "student_code": element.student_code,
                        "academic_id": element.academy_id,
                        "full_name_ar": element.student_name.ar,
                        "full_name_en": element.student_name.en
                    };
                    _this.filterRecord.student_list.push(obj);
                }
            });
            this.filterRecord.student_count = this.filterRecord.student_code_list.length;
        };
        VacationComponent.prototype.replace = function (dialogResult) {
            var _this = this;
            var studentArray = dialogResult;
            this.filterRecord.student_code_list = [];
            this.filterRecord.student_list = [];
            studentArray.forEach(function (element) {
                _this.filterRecord.student_code_list.push(element.student_code);
                var obj = {
                    "student_code": element.student_code,
                    "academic_id": element.academy_id,
                    "full_name_ar": element.student_name.ar,
                    "full_name_en": element.student_name.en
                };
                _this.filterRecord.student_list.push(obj);
            });
            this.filterRecord.student_count = this.filterRecord.student_code_list.length;
        };
