        VacationComponent.prototype.validate = function () {
            if (!this.selectedVacationSettings.id) {
                this.ui.error(this.i18n.get('academicMilitary.vacation.vacation_settings_id_err'));
                return false;
            }
            if (this.selectedVacationSettings.is_activate_restrictions && !this.selectedVacationSettings.vacation_restrictions_id) {
                this.ui.error(this.i18n.get('academicMilitary.vacation.assign_template_err'));
                return false;
            }
            return true;
        };
        VacationComponent.prototype.doSave = function () {
            if (!this.validate()) {
                return;
            }
            if (this.activeTabIndex == 0) {
                this.filterRecord.filter_type = 'tab_housing';
                this.filterRecord.study_level_id = null;
                this.filterRecord.general_program_code = null;
                this.filterRecord.precise_program_code = null;
                this.filterRecord.student_code_list = null;
            }
            else if (this.activeTabIndex == 1) {
                this.filterRecord.filter_type = 'tab_study_levels';
                this.filterRecord.battalion_id = null;
                this.filterRecord.company_id = null;
                this.filterRecord.faction_id = null;
                this.filterRecord.student_code_list = null;
            }
            else if (this.activeTabIndex == 2) {
                this.filterRecord.filter_type = 'tab_students';
                this.filterRecord.battalion_id = null;
                this.filterRecord.company_id = null;
                this.filterRecord.faction_id = null;
                this.filterRecord.study_level_id = null;
                this.filterRecord.general_program_code = null;
                this.filterRecord.precise_program_code = null;
            }
            this.masterRecord.vacation_settings_id = this.selectedVacationSettings.id;
            var servletUrl = Constants.baseUrl + '/crd/vacation';
            var formData = new FormData();
            formData.append('masterRecordData', '' + JSON.stringify(this.masterRecord));
            formData.append('masterRecordFilter', '' + JSON.stringify(this.filterRecord));
            formData.append('selectedVacationSettings', '' + JSON.stringify(this.selectedVacationSettings));
            formData.append('vacation_restrictions_id', '' + this.selectedVacationSettings.vacation_restrictions_id);
            if (this.isEditMode === '') {
                formData.append('transaction', 'insert');
                this.eSendForm(this, 'rec_insert', servletUrl, formData);
            }
            else {
                formData.append('transaction', 'update');
                this.eSendForm(this, 'rec_update', servletUrl, formData);
            }
        };
