            isAudioProcessStarted = false;
            recording = false;
            isPaused = false;
            context = null;

            self.leftchannel = leftchannel;
            self.rightchannel = rightchannel;
            self.numberOfAudioChannels = numberOfAudioChannels;
            self.desiredSampRate = desiredSampRate;
            self.sampleRate = sampleRate;
