        DetailedAdministrativePlacementComponent.prototype.getPlacementPattern = function (settings) {
            if (!settings)
                return '';
            var parts = settings.split(',').map(function (p) { return parseInt(p.trim()); });
            var bat = parts[0];
            var comp = parts[1];
            var plat = parts[2];
            var grp = parts[3];
            var compLabels = {
                ar: { 1: 'كل السرايا', 2: 'أول سرية', 3: 'آخر سرية' },
                en: { 1: 'All Companies', 2: 'First Company', 3: 'Last Company' }
            };
            var platLabels = {
                ar: { 1: 'كل الفصائل', 2: 'أول فصيلة', 3: 'وسط فصيلة', 4: 'آخر فصيلة' },
                en: { 1: 'All Platoons', 2: 'First Platoon', 3: 'Middle Platoon', 4: 'Last Platoon' }
            };
            var grpLabels = {
                ar: { 1: 'كل الجماعات', 2: 'أول جماعة', 3: 'وسط جماعة', 4: 'آخر جماعة' },
                en: { 1: 'All Groups', 2: 'First Group', 3: 'Middle Group', 4: 'Last Group' }
            };
            var arrow = this.lang === 'ar' ? ' ← ' : ' → ';
            var textParts = [];
            if (bat === 0) {
                textParts.push(this.lang === 'ar' ? 'كل الكتائب' : 'All Battalions');
            }
            else {
                var batRec = this.comboxArr_battalion.find(function (b) { return parseInt(b.id) === bat; });
                textParts.push(batRec ? batRec.name[this.lang] : 'ك' + bat);
            }
            if (comp !== 0 && compLabels[this.lang][comp])
                textParts.push(compLabels[this.lang][comp]);
            if (plat !== 0 && platLabels[this.lang][plat])
                textParts.push(platLabels[this.lang][plat]);
            if (grp !== 0 && grpLabels[this.lang][grp])
                textParts.push(grpLabels[this.lang][grp]);
            var suffix = '';
            if (grp === 0 && plat !== 0)
                suffix = this.lang === 'ar' ? ' (بدون جماعة)' : ' (no group)';
            else if (plat === 0 && comp !== 0)
                suffix = this.lang === 'ar' ? ' (بدون فصيلة)' : ' (no platoon)';
            else if (comp === 0)
                suffix = this.lang === 'ar' ? ' (بدون سرية)' : ' (no company)';
            return textParts.join(arrow) + suffix;
        };
        DetailedAdministrativePlacementComponent.prototype.getLeadershipLevel = function (level) {
            var levels = {
                ar: { 1: 'الكلية', 2: 'الكتائب', 3: 'السرايا', 4: 'الفصائل', 5: 'الجماعات' },
                en: { 1: 'College', 2: 'Battalions', 3: 'Company', 4: 'Platoons', 5: 'Groups' }
            };
            return levels[this.lang][level] || '';
        };
